import { PnpmError } from '@pnpm/error'
import { createGetAuthHeaderByURI } from '@pnpm/network.auth-header'
import { createFetchFromRegistry, type CreateFetchFromRegistryOptions } from '@pnpm/network.fetch'
import type { Registries, RegistryConfig } from '@pnpm/types'
import { renderHelp } from 'render-help'

import { rcOptionsTypes } from './common.js'

export { rcOptionsTypes }

export function cliOptionsTypes (): Record<string, unknown> {
  return {
    ...rcOptionsTypes(),
  }
}

export const commandNames = ['ping']

export function help (): string {
  return renderHelp({
    description: 'Test connectivity to the configured npm registry.',
    url: docsUrl('ping'),
    usages: [
      'pnpm ping',
    ],
  })
}

export interface PingOptions extends CreateFetchFromRegistryOptions {
  configByUri?: Record<string, RegistryConfig>
  registries?: Registries
  registry?: string
}

export async function handler (opts: PingOptions): Promise<string> {
  const registry = opts.registry ?? opts.registries?.default
  if (!registry) {
    throw new PnpmError('MISSING_REGISTRY', 'No registry configured to ping.')
  }

  // Preserve any path prefix in the registry URL. We only strip a trailing
  // slash so that `/-/ping` is appended cleanly.
  const pingUrl = `${registry.replace(/\/$/, '')}/-/ping?write=true`

  const fetchFromRegistry = createFetchFromRegistry(opts)
  const getAuthHeader = createGetAuthHeaderByURI(opts.configByUri ?? {}, opts.registries?.default)

  const start = Date.now()
  let response: Response
  try {
    response = await fetchFromRegistry(pingUrl, {
      authHeaderValue: getAuthHeader(registry),
    })
  } catch (err: unknown) {
    const message = err instanceof Error ? err.message : String(err)
    throw new PnpmError('PING_FAILED', `Failed to reach registry ${registry}: ${message}`)
  }

  if (!response.ok) {
    throw new PnpmError(
      'PING_FAILED',
      `Failed to reach registry ${registry}: ${response.status} ${response.statusText}`
    )
  }

  let body: Record<string, unknown> = {}
  try {
    body = await response.json() as Record<string, unknown>
  } catch {
    // Some registries reply to a ping with an empty body. That is fine.
  }

  const time = Date.now() - start
  const lines = [
    `PING ${registry}`,
    `PONG ${time}ms`,
  ]
  if (body != null && typeof body === 'object' && Object.keys(body).length > 0) {
    lines.push(JSON.stringify(body, null, 2))
  }
  return lines.join('\n')
}
